import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.person.Grade;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.SettingService;
import net.officefloor.hq.app.setting.SheetParentRepository;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class RateService {

    private final RateRepository rates;
    private final RateChangeRepository changes;
    private final SheetService sheets;
    private final SheetParentRepository parents;
    private final ClaimRepository claims;
    private final Rollup rollup;
    private final Audit audit;

    public RateService(RateRepository rates, RateChangeRepository changes, SheetService sheets,
            SheetParentRepository parents, ClaimRepository claims, Rollup rollup, Audit audit) {
        this.claims = claims;
        this.rates = rates;
        this.changes = changes;
        this.sheets = sheets;
        this.parents = parents;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's rates in grade order, then by from-date; a grade with no rate is left out. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdInOrder(sheetId);
    }

    /** A rate of the sheet or of one of its parents, with how many levels up it is (0: the sheet's own), and
     *  when its newest version is forward-only, its older versions, newest first, down to the newest that applies
     *  to every claim. */
    public record Inherited(int level, Rate rate, List<RateChange> older) {
    }

    /** The rates of the sheet and of its parents up to three levels up, nearest first, each in grade order,
     *  then by from-date. */
    @Transactional(readOnly = true)
    public List<Inherited> listInherited(String sheetId) {
        List<Inherited> all = new ArrayList<>();
        List<String> lineage = SettingService.lineageOf(parents, sheetId);
        AppliedRates applied = AppliedRates.of(changes, lineage);
        for (int level = 0; level < lineage.size(); level++) {
            for (Rate rate : rates.findBySheetIdInOrder(lineage.get(level))) {
                all.add(new Inherited(level, rate, applied.olderVersions(rate)));
            }
        }
        return all;
    }

    /** The rate's older versions, newest first, down to the newest that applies to every claim; none when
     *  its newest does. */
    @Transactional(readOnly = true)
    public List<RateChange> olderVersions(Rate rate) {
        if (rate.getForwardAfter() == null) return List.of();
        return AppliedRates.of(changes, List.of(rate.getSheetId())).olderVersions(rate);
    }

    /** The grade's rate in force on a date: of the sheet's rates, the one with the latest from-date on or
     *  before it, unless the date is after that rate's to-date; when none is, the parent's in force then, and
     *  so on up to three levels up; null when none is. */
    @Transactional(readOnly = true)
    public Rate inForce(String sheetId, Grade grade, LocalDate date) {
        List<List<Rate>> levels = new ArrayList<>();
        for (String id : SettingService.lineageOf(parents, sheetId)) levels.add(rates.findForGrade(id, grade));
        return Rate.inForceInherited(levels, date);
    }

    /** The grade's rate in force on a date for a claim, as {@link #inForce} tells it of the versions of the rates
     *  that apply to the claim: a forward-only version only to claims added after it was saved. */
    @Transactional(readOnly = true)
    public Rate inForceFor(String sheetId, Grade grade, LocalDate date, Long claimId) {
        List<String> lineage = SettingService.lineageOf(parents, sheetId);
        List<List<Rate>> levels = new ArrayList<>();
        for (String id : lineage) levels.add(rates.findForGrade(id, grade));
        if (levels.stream().flatMap(List::stream).allMatch((r) -> r.appliesToClaim(claimId))) {
            return Rate.inForceInherited(levels, date);
        }
        return Rate.inForceInherited(AppliedRates.of(changes, lineage).appliedLevels(levels, claimId), date);
    }

    /** The grade's rate in force on a date as the sheet's rates stood at the end of another date (asOf):
     *  every setting made while the sheet's today was on or before it counts, every later one does not;
     *  null when none is in force then. */
    @Transactional(readOnly = true)
    public Rate inForceAsOf(String sheetId, Grade grade, LocalDate date, LocalDate asOf) {
        return inForceAsOf(sheetId, grade, date, asOf, null);
    }

    /** The grade's rate in force on a date for a claim as the sheet's rates stood at the end of another date
     *  (see {@link #inForceAsOf(String, Grade, LocalDate, LocalDate)}), of the versions that apply to the claim:
     *  a forward-only version only to claims added after it was saved. */
    @Transactional(readOnly = true)
    public Rate inForceAsOf(String sheetId, Grade grade, LocalDate date, LocalDate asOf, Long claimId) {
        // The parents are those the sheet names now, each read as its rates stood at the end of the same date.
        for (String id : SettingService.lineageOf(parents, sheetId)) {
            Rate rate = ownInForceAsOf(id, grade, date, asOf, claimId);
            if (rate != null) return rate;
        }
        return null;
    }

    private Rate ownInForceAsOf(String sheetId, Grade grade, LocalDate date, LocalDate asOf, Long claimId) {
        Map<LocalDate, Rate> byFrom = new HashMap<>();
        Rate fromStart = null;
        for (RateChange change : changes.findBySheetIdOrderByIdAsc(sheetId)) {
            if (change.getGrade() != grade || !change.madeBy(asOf) || !change.appliesToClaim(claimId)) continue;
            if (change.getFrom() == null) fromStart = change.toRate();
            else byFrom.put(change.getFrom(), change.toRate());
        }
        List<Rate> gradeRates = new ArrayList<>();
        if (fromStart != null) gradeRates.add(fromStart);
        byFrom.keySet().stream().sorted().forEach((from) -> gradeRates.add(byFrom.get(from)));
        return Rate.inForce(gradeRates, date);
    }

    /** Set the sheet's rate for a grade from a from-date (none: from the beginning of time) through
     *  a to-date (none: until the grade's next rate). When the grade already has a rate for that from-date, the
     *  value it held is kept as an older version and the new one becomes its newest version, the one in force. A
     *  to-date before the from-date is refused. A rate saved with a from-date on or after the sheet's today is
     *  forward-only: that version applies only to the claims added after it is saved. */
    @Transactional
    public Rate set(String sheetId, String user, Grade grade, LocalDate from, LocalDate to, BigDecimal pct) {
        if (from != null && to != null && to.isBefore(from)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "The to-date is before the from-date.");
        }
        sheets.load(sheetId);
        Rollup.Snapshot before = rollup.snapshot(sheetId);
        LocalDate today = sheets.today(sheetId);
        Long forwardAfter = from != null && today != null && !from.isBefore(today) ? claims.maxId() : null;
        Rate rate = (from == null ? rates.findFromStart(sheetId, grade) : rates.findFrom(sheetId, grade, from))
                .orElse(null);
        if (rate == null) {
            rate = new Rate(sheetId, grade, from, to, pct, forwardAfter);
        } else {
            rate.newVersion(pct, to, forwardAfter);
        }
        Rate saved;
        try {
            saved = rates.saveAndFlush(rate);
            changes.saveAndFlush(new RateChange(saved, today));
        } catch (DataIntegrityViolationException raced) {
            // Another user set the same grade's rate for that from-date at the same moment.
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The rate was changed by someone else.");
        }
        audit.recordOnCommit("RATE_SET sheet=" + sheetId + " by=" + user + " grade=" + saved.getGrade()
                + " rate=" + saved.getPct().toPlainString() + (from == null ? "" : " from=" + from)
                + (to == null ? "" : " to=" + to));
        rollup.recordChanges(user, before);
        return saved;
    }
}
package net.officefloor.hq.app.sheet;

import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.sql.DataSource;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.asof.SheetHistory;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.ClaimService;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.SettingService;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.jdbc.support.KeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

/** Clones a sheet to another id; a steward's change. */
@Service
public class CloneService {

    /** The tables copied row for row: each with the columns copied, in the order their rows were made. */
    private static final Map<String, String> COPIED = new java.util.LinkedHashMap<>();

    static {
        COPIED.put("sheet_setting", "setting_key, setting_value");
        COPIED.put("sheet_setting_dated", "setting_key, from_date, setting_value");
        COPIED.put("setting_change", "setting_key, from_date, setting_value, made_on");
        COPIED.put("sheet_role", "user_name, role");
        COPIED.put("rate", "grade, pct, from_date, to_date, version, forward_after");
        COPIED.put("rate_change", "grade, from_date, to_date, pct, made_on, version, forward_after");
        COPIED.put("holiday", "holiday_date");
        COPIED.put("void_reason", "reason");
        COPIED.put("claim_template", "name, amount, note");
        COPIED.put("sheet_tag", "name");
        // Every period comes across open.
        COPIED.put("period", "name, name_key, from_date, to_date");
    }

    private final SheetRepository sheets;
    private final SettingService settings;
    private final PersonRepository people;
    private final ClaimRepository claims;
    private final ClaimService claimService;
    private final SheetHistory history;
    private final Rollup rollup;
    private final Audit audit;
    private final JdbcTemplate jdbc;

    @PersistenceContext
    private EntityManager entities;

    public CloneService(SheetRepository sheets, SettingService settings, PersonRepository people,
            ClaimRepository claims, ClaimService claimService, SheetHistory history, Rollup rollup, Audit audit,
            DataSource dataSource) {
        this.sheets = sheets;
        this.settings = settings;
        this.people = people;
        this.claims = claims;
        this.claimService = claimService;
        this.history = history;
        this.rollup = rollup;
        this.audit = audit;
        this.jdbc = new JdbcTemplate(dataSource);
    }

    /**
     * Clone the sheet to another id, which must never have been used. The clone gets the sheet's today,
     * settings, roles, rates, holidays, void reasons, templates, people (with everything they have), their
     * patrons, the pools, the crews, the periods (all open) and the claims (status, frozen figures, dates, notes, logs),
     * whose numbers are given afresh by the clone's own numbering in the order they were opened (by the
     * sheet's today when each was opened, then by the order they were added); statements are not copied.
     * Refused unless the user is a steward of the sheet, and when the other id is this sheet's or was used.
     */
    @Transactional
    public void cloneTo(String sheetId, String user, String toSheetId) {
        Sheet from = sheets.findById(sheetId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "No such sheet."));
        if (settings.roleOf(sheetId, user) != Role.STEWARD) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "Only a steward can clone the sheet.");
        }
        if (toSheetId.equals(sheetId) || sheets.existsById(toSheetId)) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The other sheet has already been used.");
        }
        try {
            sheets.saveAndFlush(new Sheet(toSheetId, Instant.now(), from.getToday()));
        } catch (DataIntegrityViolationException raced) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "The other sheet has already been used.");
        }

        COPIED.forEach((table, columns) -> jdbc.update("INSERT INTO " + table + " (sheet_id, " + columns + ") SELECT ?, "
                + columns + " FROM " + table + " WHERE sheet_id = ?" + (hasId(table) ? " ORDER BY id" : ""),
                toSheetId, sheetId));

        // The people, in the order they were added, then in their places in the list.
        List<Person> theirs = people.findInListOrder(sheetId);
        Map<Long, Person> clones = new HashMap<>();
        for (Person person : theirs.stream().sorted(Comparator.comparing(Person::getId)).toList()) {
            clones.put(person.getId(), people.save(person.cloneTo(toSheetId)));
        }
        people.flush();
        List<Long> places = clones.values().stream().map(Person::getId).sorted().toList();
        for (int i = 0; i < theirs.size(); i++) clones.get(theirs.get(i).getId()).placeAt(places.get(i));
        people.flush();
        Map<Long, Long> personIds = new HashMap<>();
        clones.forEach((id, clone) -> personIds.put(id, clone.getId()));

        for (Map<String, Object> patron : jdbc.queryForList(
                "SELECT person_id, patron_id FROM person_patron WHERE sheet_id = ? ORDER BY id", sheetId)) {
            jdbc.update("INSERT INTO person_patron (sheet_id, person_id, patron_id) VALUES (?, ?, ?)", toSheetId,
                    personIds.get(id(patron, "PERSON_ID")), personIds.get(id(patron, "PATRON_ID")));
        }

        Map<Long, Long> poolIds = new HashMap<>();
        for (Map<String, Object> pool : jdbc.queryForList("SELECT id, name FROM pool WHERE sheet_id = ? ORDER BY id",
                sheetId)) {
            KeyHolder key = new GeneratedKeyHolder();
            jdbc.update((connection) -> {
                PreparedStatement insert = connection.prepareStatement(
                        "INSERT INTO pool (sheet_id, name) VALUES (?, ?)", Statement.RETURN_GENERATED_KEYS);
                insert.setString(1, toSheetId);
                insert.setString(2, (String) pool.get("NAME"));
                return insert;
            }, key);
            poolIds.put(id(pool, "ID"), key.getKey().longValue());
        }
        for (Map<String, Object> member : jdbc.queryForList("SELECT m.pool_id, m.person_id, m.member_pool_id, m.share, "
                + "m.from_date, m.to_date FROM pool_member m JOIN pool p ON p.id = m.pool_id WHERE p.sheet_id = ? "
                + "ORDER BY m.id", sheetId)) {
            jdbc.update("INSERT INTO pool_member (pool_id, person_id, member_pool_id, share, from_date, to_date) "
                    + "VALUES (?, ?, ?, ?, ?, ?)", poolIds.get(id(member, "POOL_ID")),
                    personIds.get(id(member, "PERSON_ID")), poolIds.get(id(member, "MEMBER_POOL_ID")),
                    member.get("SHARE"), member.get("FROM_DATE"), member.get("TO_DATE"));
        }

        Map<Long, Long> crewIds = new HashMap<>();
        for (Map<String, Object> crew : jdbc.queryForList(
                "SELECT id, name, lead_id FROM crew WHERE sheet_id = ? ORDER BY id", sheetId)) {
            KeyHolder key = new GeneratedKeyHolder();
            jdbc.update((connection) -> {
                PreparedStatement insert = connection.prepareStatement(
                        "INSERT INTO crew (sheet_id, name, lead_id) VALUES (?, ?, ?)", Statement.RETURN_GENERATED_KEYS);
                insert.setString(1, toSheetId);
                insert.setString(2, (String) crew.get("NAME"));
                insert.setLong(3, personIds.get(id(crew, "LEAD_ID")));
                return insert;
            }, key);
            crewIds.put(id(crew, "ID"), key.getKey().longValue());
        }
        for (Map<String, Object> member : jdbc.queryForList("SELECT m.crew_id, m.person_id FROM crew_member m "
                + "JOIN crew c ON c.id = m.crew_id WHERE c.sheet_id = ? ORDER BY m.id", sheetId)) {
            jdbc.update("INSERT INTO crew_member (crew_id, person_id) VALUES (?, ?)", crewIds.get(id(member, "CREW_ID")),
                    personIds.get(id(member, "PERSON_ID")));
        }

        // The claims that had a number take the clone's, in the order they were opened.
        List<Claim> all = claims.findBySheetIdOrderByIdDesc(sheetId);
        Map<String, String> numbers = new HashMap<>();
        all.stream().filter(c -> c.getNumber() != null)
                .sorted(Comparator.comparing(Claim::openedOn, Comparator.nullsFirst(Comparator.naturalOrder()))
                        .thenComparing(Claim::getPersonId).thenComparing(Claim::getId))
                .forEach(c -> numbers.put(c.getNumber(), claimService.nextNumber(toSheetId, c)));
        List<Claim> oldestFirst = new ArrayList<>(all);
        Collections.reverse(oldestFirst);
        java.util.TreeMap<Long, Long> claimIds = new java.util.TreeMap<>();
        for (Claim claim : oldestFirst) {
            Claim copy = claim.copyTo(toSheetId, personIds.get(claim.getPersonId()), claim.getListed(),
                    numbers.get(claim.getNumber()),
                    claim.getCorrects() == null ? null : numbers.get(claim.getCorrects()),
                    claim.getSplitFrom() == null ? null : numbers.get(claim.getSplitFrom()));
            copy.setRef(claim.getRef());
            claimIds.put(claim.getId(), claims.save(copy).getId());
        }
        claims.flush();
        // A forward-only rate applies to the copies of the claims it applied to: those added after it was saved.
        for (String table : List.of("rate", "rate_change")) {
            for (Long after : jdbc.queryForList("SELECT DISTINCT forward_after FROM " + table
                    + " WHERE sheet_id = ? AND forward_after IS NOT NULL", Long.class, toSheetId)) {
                Map.Entry<Long, Long> last = claimIds.floorEntry(after);
                jdbc.update("UPDATE " + table + " SET forward_after = ? WHERE sheet_id = ? AND forward_after = ?",
                        last == null ? 0L : last.getValue(), toSheetId, after);
            }
        }
        entities.flush();

        audit.recordOnCommit("SHEET_CLONE_MADE sheet=" + sheetId + " by=" + user + " to=" + toSheetId);
        audit.recordOnCommit("SHEET_CLONED sheet=" + toSheetId + " by=" + user + " from=" + sheetId);
        rollup.recordAll(user, toSheetId);
        // The request changes this sheet, which is kept as it commits; the clone is kept here.
        history.keep(toSheetId);
    }

    private static boolean hasId(String table) {
        return !table.startsWith("sheet_setting") && !table.equals("sheet_role");
    }

    private static Long id(Map<String, Object> row, String column) {
        Object value = row.get(column);
        return value == null ? null : ((Number) value).longValue();
    }
}
